arguments.command:
cat > tests/CheckoutPricing.UnitTests/GoldDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysPayable95()
    {
        var checkoutTypes = new[] { typeof(ApplicationMarker).Assembly, typeof(DomainMarker).Assembly }
            .SelectMany(a => a.GetTypes())
            .Where(t => t.Name.Contains("Checkout") || t.Name.Contains("Pricing") || t.Name.Contains("Customer"))
            .ToList();

        Assert.True(checkoutTypes.Count > 0,
            "No checkout/pricing/customer type exists in Application or Domain; payable total (expected 95.00) cannot be calculated.");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -20

